        "accounting_quality_standard": {
          "heading": "Accurate Books. Reconciled Records. GST-Ready Documentation.",
          "principle": "Balanced Books Are Necessary but Not Proof That Every Entry Is Correct. An automated trial balance or bank match does not guarantee accounting correctness. Every voucher must be backed by valid source documentation, correct account classification, proper tax rates, and independent verification.",
          "error_correction_rule": "Never delete or alter records merely to force reports to balance. Discrepancies must be investigated to their source, corrected with authorized adjustment vouchers, and supported by a clear audit trail."
        },
        "gst_legal_update_policy": {
          "heading": "GST Rate, Threshold & Statutory Update Standard",
          "rule": "GST rates, thresholds, and reporting formats in India evolve. Nova Skills teaches tax concepts using current official rules applicable to exercise transaction dates. No tax rate is taught as universally permanent. Official source hierarchy: (1) CBIC notifications & statutory law, (2) GST Portal official guidelines, (3) GST Council announcements, (4) e-Invoice/e-Way Bill portals, (5) TallyHelp for software mechanics."
        },
        "gstr1_reconciliation_policy": {
          "heading": "GSTR-1 Outward Supply Practical Reconciliation",
          "workflow": "Separate outward supply reconciliation comparing Tally sales registers with synthetic portal return data across invoice numbers, GSTINs, dates, taxable values, and tax amounts. Categorized into Matched, Missing in Books, Missing on Portal, and Value Mismatches."
        },
        "gstr2b_itc_reconciliation_policy": {
          "heading": "GSTR-2B & Input Tax Credit Practical Reconciliation",
          "workflow": "Separate inward purchase reconciliation comparing company purchase registers against synthetic GSTR-2B statements. Students audit Section 16 eligibility, identify blocked credits under Section 17(5), and generate supplier follow-up registers for missing invoices."
        },
        "ims_awareness_policy": {
          "heading": "Invoice Management System (IMS) Awareness",
          "concepts": "Recipient review of supplier-uploaded invoices with actions: Accept, Reject, Keep Pending. Understanding how IMS decisions flow into GSTR-2B recomputations and subsequent GSTR-3B tax offset calculations."
        },
        "einvoicing_ewaybill_safety_policy": {
          "heading": "Electronic Invoicing & e-Way Bill Educational Safety",
          "mandate": "Strict prohibition against connecting to live government IRP or e-way bill portals. Concepts of IRNs, signed QR codes, and transporter Part-B details are taught using structured JSON templates, synthetic payloads, and simulated workflows. Awareness of August 1, 2026 Ship-To GSTIN requirements included."
        },
        "gstr9_preparation_policy": {
          "heading": "GSTR-9 Annual Preparation vs Actual Filing Distinction",
          "distinction": "TallyPrime Release 7.2 facilitates local data aggregation and GSTR-9 export. This is local preparation, NOT statutory return filing. Professional tax filing requires authorized credentials and review by qualified Chartered Accountants."
        },
        "edit_log_security_policy": {
          "heading": "Edit Log, Audit Trails & Company Data Security",
          "standards": "Understanding the MCA audit-trail mandate and the operational distinction between standard TallyPrime and TallyPrime Edit Log. Enforcing user security controls, multi-destination backup archives, and zero exposure of confidential business records."
        },
