    "prompt_quality_framework": {
      "heading": "Better Context. Better Questions. Better Review.",
      "principles": [
        {
          "step": 1,
          "name": "Task",
          "description": "State precisely what Copilot should do (draft, summarize, analyze, extract, or explain)."
        },
        {
          "step": 2,
          "name": "Context",
          "description": "Explain why the task is being performed and provide background business circumstances."
        },
        {
          "step": 3,
          "name": "Source",
          "description": "Reference authorized files, notes, or data rows that must serve as the sole factual basis."
        },
        {
          "step": 4,
          "name": "Audience",
          "description": "Define who will read or use the output (executives, clients, operations staff, or team members)."
        },
        {
          "step": 5,
          "name": "Constraints",
          "description": "Set negative boundaries (no invented facts, specific length limits, excluded topics, or confidentiality rules)."
        },
        {
          "step": 6,
          "name": "Format",
          "description": "Specify output structure (bulleted list, executive memo, tabular layout, or presentation outline)."
        },
        {
          "step": 7,
          "name": "Verification",
          "description": "Instruct Copilot to flag assumptions, cite sources, or mark items requiring human confirmation."
        }
      ],
      "examples": {
        "word": "Using the supplied fictional operations notes, draft a one-page management summary. Include only supported findings. Do not invent figures, customer names or decisions. Mark missing information as needing confirmation.",
        "excel": "Analyze the provided sales data by month and category. Explain the formulas and list the source columns used. Do not invent data. Highlight assumptions, then provide calculations I can verify manually.",
        "powerpoint": "Create a proposed presentation outline from the approved report. Preserve all dates and figures exactly, avoid unsupported claims, and identify content that requires visual or factual review.",
        "meeting": "Summarize the supplied fictional transcript. Extract only decisions and action items explicitly stated. Do not invent owners or deadlines. Mark unclear ownership as unconfirmed."
      },
      "teaching_point": "A more detailed prompt can improve outputs, but it cannot guarantee accuracy. Human verification remains mandatory."
    },
