    "microsoft_graph_work_iq_policy": {
      "heading": "Copilot Can Use Authorized Work Context—not Every File in the Organization.",
      "principles": [
        "Copilot respects organizational permissions and only accesses information the authenticated user has explicit permission to view.",
        "Oversharing Risk Awareness: If internal folders or SharePoint sites have overly broad permissions, Copilot can surface sensitive content unintentionally. Students are taught to audit document permissions.",
        "Least Privilege Standard: Always restrict working files to necessary collaborators before referencing them in AI prompts.",
        "Synthetic Classroom Scenarios: All exercises use isolated synthetic datasets representing public business policy, team project reports, and fictional restricted documents."
      ]
    },
    "ai_output_verification_standard": {
      "heading": "Never Approve an AI Result You Cannot Explain or Check.",
      "workflow": "Generate → Inspect → Compare → Recalculate → Correct → Approve",
      "verification_types": [
        {
          "type": "Factual Verification",
          "scope": "Verify all names, dates, quotes, references, and operational business details against original notes."
        },
        {
          "type": "Numerical Verification",
          "scope": "Perform 100% independent manual recalculation of totals, percentages, formula ranges, and trend calculations."
        },
        {
          "type": "Documentary Verification",
          "scope": "Audit source alignment, eliminate omitted caveats, and remove fabricated or hallucinated citations."
        },
        {
          "type": "Communication Verification",
          "scope": "Check recipient lists, subject lines, tone appropriateness, commitments made, and action item ownership."
        },
        {
          "type": "Visual Verification",
          "scope": "Inspect slide legibility, chart scales, axis labels, and ensure graphics do not mislead the audience."
        },
        {
          "type": "Governance Verification",
          "scope": "Confirm that source data was authorized for use, adheres to privacy rules, and has documented human sign-off."
        }
      ],
      "common_errors_caught": [
        "Hallucinated operational facts and dates",
        "Wrong formula syntax and incorrect Excel ranges",
        "Invented meeting commitments and misassigned owners",
        "Misread source document conclusions",
        "Omitted safety caveats and financial assumptions"
      ]
    },
    "teams_meeting_intelligence_policy": {
      "heading": "Meeting Intelligence & Consent Governance",
      "principles": [
        "Live During-Meeting Copilot can assist with questions in real time without requiring persistent transcripts when enabled by organizers.",
        "Post-Meeting Recaps and action-item tracking strictly require meeting recording or transcription.",
        "Zero Unauthorized Recording: No learner is ever required or permitted to record real workplace meetings without explicit attendee consent. Classroom labs utilize fictional transcripts."
      ]
    },
    "excel_ai_reliability_policy": {
      "heading": "Use AI to Assist Analysis. Keep the Calculations Verifiable.",
      "mandatory_checks": [
        "Confirm source dataset is structured with clear headers and no merged header cells.",
        "Verify that Copilot correctly identified the intended target columns.",
        "Audit formula logic: ensure range bounds and criteria match the business question.",
        "Validate date parsing and period groupings.",
        "Recalculate key totals and category summaries manually.",
        "Reconcile chart values directly against raw spreadsheet tables.",
        "Confirm that analytical conclusions are supported by actual numerical evidence.",
        "Disclose analytical limitations and assumptions in executive summaries."
      ],
      "scope_boundary": "Focuses on everyday spreadsheet reporting and formula verification; excludes advanced Power Query, complex DAX, Power BI, and Python in Excel."
    },
    "responsible_ai_policy": {
      "heading": "Responsible AI, Privacy & Workplace Data Safety",
      "core_rules": [
        "Human Accountability: The user, not the AI, bears full professional responsibility for all approved documents, numbers, and communications.",
        "Confidential Data Protection: Never enter sensitive personal identifiable information (PII), confidential client contracts, or trade secrets into public AI tools.",
        "Prompt Injection Defense: Inspect external or unvetted source documents for hidden malicious instructions before feeding them to Copilot.",
        "Transparent AI Disclosure: Document where AI assistance was utilized and maintain a human verification audit trail."
      ]
    },
